// Transform upstream order payload for the downstream CRM API.
// NOTE: this node contains two intentional bugs (demo fixture).
const payload = $input.first().json.body;

// BUG 1 — type mismatch: upstream sends `total` as a STRING ("49.90"),
// this code assumes a number. Throws TypeError at runtime.
const total = payload.total.toFixed(2);

// BUG 2 — wrong mapping: upstream nests the id at payload.customer.id.
// This line reads a field that does not exist, so customerId becomes null
// and the downstream API receives an incomplete record.
const customerId = payload.customer_id;

const itemCount = payload.items.length;

return [
  {
    json: {
      customerId,
      itemCount,
      total,
      status: 'processed'
    }
  }
];
